<!-- app/components/shared/GearLogo.vue
     The Gear logo: two gears and the word "Gear", copied from "Logo Gear.svg" in Figma.
     It lives in components/shared, so every page can use it as <GearLogo /> (no import needed, Nuxt auto-imports it).
     Usage: <GearLogo />            (86 x 28 px, the size in Figma)
            <GearLogo :width="129" /> (bigger, the height follows so the proportions stay the same) -->
<script lang="ts">
export default defineComponent({
  props: {
    // Width in pixels. The height is calculated from it
    width: { type: Number, default: 86 },
  },
  computed: {
    // The original logo is 86 x 28, so the height is always 28/86 of the width
    height(): number {
      return (this.width * 28) / 86;
    },
  },
});
</script>

